    df['grade'] = pd.Categorical(df['grade'], categories=['A', 'B', 'C', 'D'])
    stats = df.groupby('grade')['score'].mean()
    mask = np.in1d(df['error_code'], critical_codes)
    critical_df = df[mask].set_index('batch_id')
    if not critical_df.empty:
        first_val = critical_df['score'][0]
        last_val = critical_df['score'][-1]
        return (stats.to_dict(), (first_val + last_val) / 2)
    return (stats.to_dict(), None)

