def calculate_campaign_efficiency(df, target_rate):
    group = df.groupby('campaign').agg({'clicks': 'sum', 'opens': 'sum'})
    rows = [{'campaign': 'total', 'score': 0.0}]
    for (name, row) in group.iterrows():
        rate = float(row['clicks']) / float(row['opens']) if row['opens'] > 0 else 0.0
        score = rate * 100 if rate >= target_rate else float(0.0)
        rows.append({'campaign': name, 'score': score})
    return pd.DataFrame(rows)

