def normalize_sensor_readings(df, columns):
    processed_cols = {}
    for col in columns:
        vals = df[col].values
        common_dtype = np.find_common_type([vals.dtype, np.float64], [])
        casted_vals = vals.astype(common_dtype)
        mean = np.nanmean(casted_vals)
