def normalize_listing_metrics(df, metric_cols):
    data = df[metric_cols].values
    types = [data.dtype] + [np.dtype(df[c].dtype) for c in metric_cols]
    common = np.find_common_type(types, [])
    normalized = (data - np.nanmean(data, axis=0)) / np.nanstd(data, axis=0)
    return pd.DataFrame(normalized.astype(common), columns=metric_cols, index=df.index)

