def calculate_regional_yields(df, baseline_coeffs):
    yield_series = df.groupby(['region', 'crop'])['tonnes'].sum()
    regional_sums = yield_series.sum(level=0)
    norm_yields = yield_series / regional_sums
    weights = np.row_stack([norm_yields.values, baseline_coeffs])
    return np.sum(weights, axis=0)

