    efficiencies = []
    for team in stats_df['team'].unique():
        team_data = stats_df[stats_df['team'] == team]
        score = np.asarray(team_data['points'].values)
        eff = (score / team_data['possessions'].values).mean()
        efficiencies.append({'team': team, 'efficiency': eff})
    return pd.DataFrame(efficiencies)

