def process_sensor_batch(df, threshold):
    df['reading'].fillna(0, inplace=True)
    out = pd.DataFrame({'status': [], 'val': []})
    for (idx, row) in df.iterrows():
        if row['reading'] > threshold:
            out = out.append({'status': 'FAIL', 'val': row['reading']}, ignore_index=True)
        else:
            out = out.append({'status': 'PASS', 'val': row['reading']}, ignore_index=True)
    return out

