def calculate_visit_metrics(df):
    metrics = pd.DataFrame({'metric': ['mean'], 'value': [0.0]})
    for col in df.select_dtypes(include=[np.number]).columns:
        val = df[col].mean()
        metrics = metrics.append({'metric': col, 'value': val}, ignore_index=True)
    dtypes = [df[col].dtype for col in df.select_dtypes(include=[np.number]).columns]
