def calculate_team_metrics(df):
    results = pd.DataFrame({'team': [], 'avg_score': [], 'win_rate': []})
    teams = df['team'].unique()
    for team in teams:
        team_df = df[df['team'] == team]
        avg = team_df['score'].mean()
        wr = (team_df['result'] == 'W').mean()
        results = results.append({'team': team, 'avg_score': avg, 'win_rate': wr}, ignore_index=True)
    stats_matrix = np.row_stack([results['avg_score'].values, results['win_rate'].values])
    return pd.DataFrame(stats_matrix.T, columns=['avg_score', 'win_rate'], index=results['team'])

