def calculate_student_weighted_averages(df, weights):
    rows = []
    for student in df['student'].unique():
        subset = df[df['student'] == student]
        raw_scores = np.array(subset['grade'].values, dtype=float)
        weighted_sum = np.sum(raw_scores * weights) / np.sum(weights)
