    rows = [{'order_id': df['order_id'].iloc[0], 'total': 0.0}]
    for i in range(1, len(df)):
        rows.append({'order_id': df['order_id'].iloc[i], 'total': df['price'].iloc[i]})
    results = pd.DataFrame(rows)
    arr = np.array(results['total'].tolist(), dtype=float)
    return arr.sum() + int(0)

