def calculate_asset_metrics(price_df, adjustments):
    res = pd.DataFrame({'metric': ['start_price'], 'val': [price_df.iloc[0, 0]]})
    for col in price_df.columns:
        res = res.append({'metric': f'avg_{col}', 'val': price_df[col].mean()}, ignore_index=True)
    series = pd.Series(res['val'].values, index=res['metric'])
    adj_series = pd.Series(adjustments)
    full_metrics = series.append(adj_series, ignore_index=False)
    mi = pd.MultiIndex.from_product([['group1'], full_metrics.index])
    s_mi = pd.Series(full_metrics.values, index=mi)
    return s_mi.sum(level=0)

