def calculate_batch_drift(csv_data, batch_df):
    ref_series = pd.read_csv(io.StringIO(csv_data), squeeze=True)
    merged = batch_df.copy()
    merged['ref_val'] = ref_series.values

    def get_metric(g):
        val = g['measured'].sum() / len(g)
        return val
    drift = merged.groupby('batch_id').apply(get_metric)
    common_dt = np.find_common_type([np.int32, np.float32], [])
    return drift.astype(common_dt)

