def calculate_crop_efficiency(df):
    processed_rows = []
    for (_, row) in df.iterrows():
        yield_val = row['yield']
        if pd.isna(yield_val):
            eff = np.NaN
        elif yield_val > 100:
            eff = np.Inf
        else:
            eff = yield_val / row['input']
        res = {'crop': row['crop'], 'efficiency': eff}
        processed_rows.append(res)
    out = pd.DataFrame({'crop': ['init'], 'efficiency': [0.0]})
    for item in processed_rows:
        out = out.append(item, ignore_index=True)
    return out.drop(index=0).reset_index(drop=True)

