def consolidate_inventory_logs(base_stock, logs):
    df_stock = base_stock.copy()
    for (idx, row) in logs.iterrows():
        if row['change'] != 0:
            update = {'sku': row['sku'], 'qty': row['change']}
            df_stock = df_stock.append(update, ignore_index=True)
    df_stock['qty'] = df_stock['qty'].fillna(0)
    summary = df_stock.groupby('sku')['qty'].sum().reset_index()
    return summary

