def calculate_campaign_roi(campaign_data):
    summary = pd.DataFrame({'campaign': ['Total'], 'revenue': [0.0], 'cost': [0.0]})
    for (_, row) in campaign_data.iterrows():
        summary = summary.append({'campaign': row['campaign'], 'revenue': row['revenue'], 'cost': row['cost']}, ignore_index=True)
    conv_rates = campaign_data['conversion_rate'].values
    overall_prod = np.product(conv_rates)
    all_positive = np.alltrue(conv_rates > 0)
    summary['roi'] = (summary['revenue'] - summary['cost']) / summary['cost']
    return (summary, overall_prod, all_positive)

