def calculate_inventory_valuation(inventory_df, pricing_df):
    summary_data = []
    categories = inventory_df['category'].unique()
    for cat in categories:
        cat_items = inventory_df[inventory_df['category'] == cat]
        cat_prices = pricing_df.set_index('item_id')
        value = 0.0
        for (_, row) in cat_items.iterrows():
            price = cat_prices.loc[row['item_id'], 'price']
            value += row['quantity'] * price
        summary_data.append({'category': cat, 'total_value': value})
    return pd.DataFrame(summary_data)

