def calculate_stock_replenishment(df):
    replenishments = pd.DataFrame({'sku': [df['sku'].iloc[0]], 'qty': [0]})
    for (idx, row) in df.iterrows():
        if row['current_stock'] < row['min_threshold']:
            qty = row['min_threshold'] - row['current_stock']
            replenishments = replenishments.append({'sku': row['sku'], 'qty': qty}, ignore_index=True)
    stock_arr = np.array([np.NaN, np.Inf])
    weights = np.row_stack([df[['current_stock', 'min_threshold']].values, stock_arr])
    return (replenishments, weights)

