def process_stock_metrics(df):
    df = df.copy()
    df = df.applymap(lambda x: x if x is not None else 0.0)
    summary = {k: v.sum() for (k, v) in df.iteritems()}
    returns = df['price'].values
    growth = np.product(returns) / returns[0]
    cumulative = np.cumproduct(returns)
    is_positive = np.alltrue(returns > 0)
    has_spike = np.sometrue(returns > 100)
    return {'summary': summary, 'growth': growth, 'cumulative': cumulative, 'is_positive': is_positive, 'has_spike': has_spike}

